<section id="domaines" class="admin-panel neu-flat"><p class="eyebrow">VOTRE PARCOURS</p><h2>Les domaines de votre légende</h2><div class="category-progress-grid"><?php foreach($categoriesProgress as $category): ?><div data-category-progress="<?= e($category['id']??'') ?>" class="category-progress category-<?= e(App\Services\CategoryIdentity::tone($category['slug']??null)) ?>"><div><span><?php if(preg_match('/^#[a-f0-9]{6}$/iD',$category['color']??'')): ?><svg width="10" height="10" aria-hidden="true"><circle cx="5" cy="5" r="4" fill="<?= e($category['color']) ?>"/></svg> <?php endif; ?><?= e($category['name']) ?></span><strong><?= $category['obtained'] ?> / <?= $category['total'] ?></strong></div><progress max="<?= max(1,$category['total']) ?>" value="<?= $category['obtained'] ?>" aria-label="<?= e('Progression : '.$category['name']) ?>"></progress></div><?php endforeach; ?></div><?php if(!$categoriesProgress): ?><p>Aucune catégorie disponible.</p><?php endif; ?></section>
